import itertools
import json

def solve():
    # Houses, Names, and Occupations as per the puzzle
    houses = [1, 2, 3, 4]
    names = ["Arnold", "Eric", "Peter", "Alice"]
    occupations = ["doctor", "engineer", "artist", "teacher"]

    solutions = []

    # Iterate over all permutations of names across houses
    for name_perm in itertools.permutations(names):
        # Map house -> name
        house_to_name = {house: name_perm[i] for i, house in enumerate(houses)}
        name_to_house = {v: k for k, v in house_to_name.items()}

        # Clue 1: There are two houses between Eric and Peter (i.e., distance of 3)
        if abs(name_to_house["Eric"] - name_to_house["Peter"]) != 3:
            continue

        # Clue 3: Peter is not in the first house
        if name_to_house["Peter"] == 1:
            continue

        # Iterate over all permutations of occupations across houses
        for occ_perm in itertools.permutations(occupations):
            house_to_occ = {house: occ_perm[i] for i, house in enumerate(houses)}
            occ_to_house = {v: k for k, v in house_to_occ.items()}

            # Clue 2: The person who is a teacher is Peter (i.e., teacher's house == Peter's house)
            if occ_to_house["teacher"] != name_to_house["Peter"]:
                continue

            # Clue 5: The person who is an artist is Alice
            if occ_to_house["artist"] != name_to_house["Alice"]:
                continue

            # Clue 4: There is one house between the person who is a doctor and Alice (distance 2)
            if abs(occ_to_house["doctor"] - name_to_house["Alice"]) != 2:
                continue

            # All constraints satisfied; record solution
            solutions.append((house_to_name, house_to_occ))

    # Expect a unique solution; if multiple, take the first
    if not solutions:
        raise RuntimeError("No solution found under the given constraints.")
    house_to_name, house_to_occ = solutions[0]

    # Prepare JSON output
    header = ["House", "Name", "Occupation"]
    rows = []
    for h in sorted(houses):
        rows.append([str(h), house_to_name[h], house_to_occ[h]])

    result = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(result, ensure_ascii=False))

if __name__ == "__main__":
    solve()
